package com.safebaba.controller;
import com.safebaba.dto.AuthDtos; import com.safebaba.model.*; import com.safebaba.repository.*; import com.safebaba.security.JwtUtils; import com.safebaba.service.*; import jakarta.validation.Valid; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final UsuarioService us; private final PaiService ps; private final BabaService bs; private final JwtUtils jwt; private final UsuarioRepository ur; private final PasswordEncoder encoder;
 public AuthController(UsuarioService us,PaiService ps,BabaService bs,JwtUtils jwt,UsuarioRepository ur,PasswordEncoder encoder){this.us=us;this.ps=ps;this.bs=bs;this.jwt=jwt;this.ur=ur;this.encoder=encoder;}
 @PostMapping("/register") public AuthDtos.AuthResponse register(@Valid @RequestBody AuthDtos.RegistroRequest r){Usuario u=new Usuario();u.setNome(r.nome());u.setEmail(r.email());u.setSenha(r.senha());u.setTelefone(r.telefone());u.setDataNascimento(r.dataNascimento());u.setCidade(r.cidade());u.setEstado(r.estado().toUpperCase());u.setTipo(r.tipo());u=us.salvar(u); if(r.tipo()==TipoUsuario.PAI){PaiResponsavel p=new PaiResponsavel();p.setUsuario(u);ps.salvar(p);} if(r.tipo()==TipoUsuario.BABA){Baba b=new Baba();b.setUsuario(u);b.setDescricao(r.descricao());b.setExperienciaAnos(r.experienciaAnos());b.setValorHora(r.valorHora()==null?BigDecimal.valueOf(0):r.valorHora());b.setDisponibilidade(r.disponibilidade());bs.salvar(b);} return new AuthDtos.AuthResponse(jwt.gerar(u.getEmail()),u.getId(),u.getNome(),u.getEmail(),u.getTipo(),"Cadastro realizado com sucesso.");}
 @PostMapping("/login") public AuthDtos.AuthResponse login(@Valid @RequestBody AuthDtos.LoginRequest r){Usuario u=ur.findByEmailIgnoreCase(r.email()).orElseThrow(()->new IllegalArgumentException("E-mail ou senha inválidos.")); if(!encoder.matches(r.senha(),u.getSenha())) throw new IllegalArgumentException("E-mail ou senha inválidos."); return new AuthDtos.AuthResponse(jwt.gerar(u.getEmail()),u.getId(),u.getNome(),u.getEmail(),u.getTipo(),"Login realizado.");}
}
